Phase 48 is correctly locked. The repository now has the intended boundary: successful Runtime responses pass artifacts, competencies, timeline, and Runtime state through unchanged; only module topology is merged with the certified UI contract.  The hook falls back to certifiedBaseline() only when the Runtime request throws.
Proceed with M50 Phase 49 — Learning Production Runtime-Truth Re-Certification. This is read-only:
Bashnpx tsx <<'TS'
import assert from "node:assert/strict";

import {
  certifiedBaseline,
  runtimeCompatibleDashboard,
} from "./apps/lumina-builder/src/components/workspaces/knowledge/learning/state/EducationalRuntimeCompatibility.ts";

import {
  runtimeGenesisReplaySelection,
  runtimeGenesisCanonicalConsumption,
  runtimeKnowledgeEducationProjectionService,
} from "./apps/lumina-runtime/src/index.ts";


if (
  runtimeGenesisReplaySelection.state !==
    "SELECTED"
) {
  throw new Error(
    `phase49_replay_selection:${runtimeGenesisReplaySelection.state}`,
  );
}


if (
  runtimeGenesisCanonicalConsumption.state !==
    "ACTIVE"
) {
  throw new Error(
    `phase49_canonical_consumption:${runtimeGenesisCanonicalConsumption.state}`,
  );
}


/*
 * 1. Certify the actual Runtime Education projection.
 */
const runtime =
  runtimeKnowledgeEducationProjectionService
    .snapshot();

const compatible =
  runtimeCompatibleDashboard({
    state:
      runtime.state,

    artifacts:
      runtime.artifacts,

    modules:
      runtime.modules,

    competencies:
      runtime.competencies,

    timeline:
      runtime.timeline,
  });


assert.deepEqual(
  compatible.artifacts,
  runtime.artifacts,
  "Builder must preserve authoritative Runtime artifacts exactly",
);

assert.deepEqual(
  compatible.competencies,
  runtime.competencies,
  "Builder must preserve authoritative Runtime competencies exactly",
);

assert.deepEqual(
  compatible.timeline,
  runtime.timeline,
  "Builder must preserve authoritative Runtime timeline exactly",
);

assert.equal(
  compatible.state,
  runtime.state,
  "Builder must preserve authoritative Runtime state",
);


/*
 * 2. Certify authoritative-empty behavior explicitly.
 */
const authoritativeEmpty =
  runtimeCompatibleDashboard({
    state:
      "success",

    artifacts:
      [],

    modules:
      [],

    competencies:
      [],

    timeline:
      [],
  });


assert.deepEqual(
  authoritativeEmpty.artifacts,
  [],
);

assert.deepEqual(
  authoritativeEmpty.competencies,
  [],
);

assert.deepEqual(
  authoritativeEmpty.timeline,
  [],
);


/*
 * 3. Certify the fallback itself remains neutral.
 *
 * This baseline is used only by the hook's error path and initial
 * render. It may preserve certified topology, but it must not claim
 * measured module progress.
 */
const fallback =
  certifiedBaseline();


for (
  const module
  of fallback.modules
) {
  assert.equal(
    module.completion,
    0,
    `fallback module ${module.id} manufactured progress`,
  );

  assert.ok(
    module.status ===
      "not-started" ||
    module.status ===
      "blocked",
    `fallback module ${module.id} has non-neutral status ${module.status}`,
  );
}


const suppressed =
  new Set(
    runtimeGenesisCanonicalConsumption
      .suppressedCanonicalIds,
  );

const runtimeArtifactIds =
  runtime.artifacts.map(
    artifact =>
      artifact.id,
  );


for (
  const canonicalId
  of suppressed
) {
  assert.equal(
    runtimeArtifactIds.includes(
      canonicalId,
    ),
    false,
    `suppressed canonical leaked into Runtime Education: ${canonicalId}`,
  );
}


console.log(
  JSON.stringify(
    {
      replaySelection:
        runtimeGenesisReplaySelection.state,

      canonicalConsumption:
        runtimeGenesisCanonicalConsumption.state,

      suppressedCanonicalIds:
        [
          ...suppressed,
        ],

      productionRuntimeEducation: {
        state:
          runtime.state,

        artifacts:
          runtime.artifacts.length,

        modules:
          runtime.modules.length,

        competencies:
          runtime.competencies.length,

        timeline:
          runtime.timeline.length,
      },

      builderCompatibility: {
        artifactIdsPreserved:
          compatible.artifacts.map(
            artifact =>
              artifact.id,
          ),

        authoritativeEmptyArtifacts:
          authoritativeEmpty
            .artifacts
            .length,

        authoritativeEmptyCompetencies:
          authoritativeEmpty
            .competencies
            .length,

        authoritativeEmptyTimeline:
          authoritativeEmpty
            .timeline
            .length,
      },

      runtimeFailureFallback: {
        moduleCount:
          fallback.modules.length,

        allModuleProgressNeutral:
          fallback.modules.every(
            module =>
              module.completion ===
              0,
          ),
      },
    },
    null,
    2,
  ),
);


console.log(
  "PASS: M50 Phase 49 Learning production Runtime-truth certification"
);
